#!/usr/bin/env node
// Task-local replacement for scripts/email-contacts.js (avoids missing minimist dep).
// Fetches contacts from the email API using only Node built-ins.

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill.onrender.com';

function parseArgv(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i++) {
    const tok = argv[i];
    if (tok.startsWith('--')) {
      const key = tok.slice(2);
      const value = argv[i + 1];
      args[key] = value !== undefined && !String(value).startsWith('--') ? value : true;
      if (args[key] !== true) i++;
    }
  }
  return args;
}

async function main() {
  const args = parseArgv(process.argv.slice(2));
  const apiKey = args['api-key'];
  const userEmail = args['user-email'];

  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }

  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || `Failed to get contacts (HTTP ${response.status})`);
  }

  return {
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  };
}

main()
  .then(result => {
    console.log(JSON.stringify(result, null, 2));
  })
  .catch(error => {
    console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
    process.exit(1);
  });

#!/usr/bin/env node
// Task-local replica of the email-api skill's scripts/email-contacts.js
// (dependency-free: no minimist; uses only Node built-ins / global fetch).
// Sends GET {base}/contacts with X-API-Key and X-User-Email headers only.

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill.onrender.com';

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a.startsWith('--')) {
      const key = a.slice(2);
      const next = argv[i + 1];
      if (next !== undefined && !next.startsWith('--')) {
        args[key] = next;
        i++;
      } else {
        args[key] = true;
      }
    }
  }
  return args;
}

async function getContacts(args) {
  const apiKey = args['api-key'];
  const userEmail = args['user-email'];

  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }

  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || 'Failed to get contacts');
  }

  return {
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  };
}

const args = parseArgs(process.argv.slice(2));

getContacts(args)
  .then(result => {
    console.log(JSON.stringify(result, null, 2));
  })
  .catch(error => {
    console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
    process.exit(1);
  });
